package tools

// docstomarkdown_golden_test.go — golden parity between docsJsonToMarkdown
// and upstream docsToMarkdown.js. The golden file is generated by executing
// the real upstream implementation in Node (see agent run; regenerable with
// the same gen script that produces markdown_golden.json). Regenerate only
// against the same pinned upstream version, and diff intentionally.

import (
	"encoding/json"
	"os"
	"testing"
)

func TestDocsJSONToMarkdown_Golden(t *testing.T) {
	data, err := os.ReadFile("testdata/docstomarkdown_golden.json")
	if err != nil {
		t.Fatalf("read golden: %v", err)
	}
	var cases map[string]struct {
		Doc  map[string]any `json:"doc"`
		Want string         `json:"want"`
	}
	// Golden file is { name: markdown } paired with inputs embedded below.
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		t.Fatalf("parse golden: %v", err)
	}
	_ = cases
	// Inputs are duplicated in the test (the golden file stores only outputs).
	inputs := map[string]string{
		"simple-para":        `{"body":{"content":[{"paragraph":{"elements":[{"textRun":{"content":"Hello world.\n"}}]}}]}}`,
		"heading+para":       `{"body":{"content":[{"paragraph":{"paragraphStyle":{"namedStyleType":"HEADING_1"},"elements":[{"textRun":{"content":"Title\n"}}]}},{"paragraph":{"elements":[{"textRun":{"content":"Body text.\n"}}]}}]}}`,
		"title-subtitle":     `{"body":{"content":[{"paragraph":{"paragraphStyle":{"namedStyleType":"TITLE"},"elements":[{"textRun":{"content":"Doc Title\n"}}]}},{"paragraph":{"paragraphStyle":{"namedStyleType":"SUBTITLE"},"elements":[{"textRun":{"content":"Sub\n"}}]}}]}}`,
		"inline-formats":     `{"body":{"content":[{"paragraph":{"elements":[{"textRun":{"content":"plain "}},{"textRun":{"content":"bold","textStyle":{"bold":true}}},{"textRun":{"content":" "}},{"textRun":{"content":"italic","textStyle":{"italic":true}}},{"textRun":{"content":" "}},{"textRun":{"content":"both","textStyle":{"bold":true,"italic":true}}},{"textRun":{"content":" "}},{"textRun":{"content":"strike","textStyle":{"strikethrough":true}}},{"textRun":{"content":" "}},{"textRun":{"content":"under","textStyle":{"underline":true}}},{"textRun":{"content":" "}},{"textRun":{"content":"linked","textStyle":{"link":{"url":"https://x.example"}}}},{"textRun":{"content":" "}},{"textRun":{"content":"ulink","textStyle":{"underline":true,"link":{"url":"https://u.example"}}}},{"textRun":{"content":" "}},{"textRun":{"content":"code","textStyle":{"weightedFontFamily":{"fontFamily":"Roboto Mono"}}}},{"textRun":{"content":"\n"}}]}}]}}`,
		"lists":              `{"body":{"content":[{"paragraph":{"bullet":{"listId":"l1","nestingLevel":0},"elements":[{"textRun":{"content":"bullet one\n"}}]}},{"paragraph":{"bullet":{"listId":"l1","nestingLevel":1},"elements":[{"textRun":{"content":"nested\n"}}]}},{"paragraph":{"bullet":{"listId":"l2","nestingLevel":0},"elements":[{"textRun":{"content":"ordered one\n"}}]}}]},"lists":{"l1":{"listProperties":{"nestingLevels":[{"glyphSymbol":"\u25cf"},{"glyphSymbol":"\u25cb"}]}},"l2":{"listProperties":{"nestingLevels":[{"glyphType":"DECIMAL"}]}}}}`,
		"table":              `{"body":{"content":[{"table":{"tableRows":[{"tableCells":[{"content":[{"paragraph":{"elements":[{"textRun":{"content":"H1\n"}}]}}]},{"content":[{"paragraph":{"elements":[{"textRun":{"content":"H2\n"}}]}}]}]},{"tableCells":[{"content":[{"paragraph":{"elements":[{"textRun":{"content":"a\nb\n"}}]}}]},{"content":[{"paragraph":{"elements":[{"textRun":{"content":"c"}}]}}]}]}]}}]}}`,
		"code-block-table":   `{"body":{"content":[{"table":{"tableRows":[{"tableCells":[{"tableCellStyle":{"backgroundColor":{"color":{"rgbColor":{"red":0.95,"green":0.95,"blue":0.95}}}},"content":[{"paragraph":{"elements":[{"textRun":{"content":"line1\nline2\n"}}]}}]}]}]}}]}}`,
		"section-break":      `{"body":{"content":[{"paragraph":{"elements":[{"textRun":{"content":"before\n"}}]}},{"sectionBreak":{}},{"paragraph":{"elements":[{"textRun":{"content":"after\n"}}]}}]}}`,
		"empty":              `{"body":{}}`,
		"trailing-nl-format": `{"body":{"content":[{"paragraph":{"elements":[{"textRun":{"content":"bold nl\n","textStyle":{"bold":true}}}]}}]}}`,
		"heading-7-plus":     `{"body":{"content":[{"paragraph":{"paragraphStyle":{"namedStyleType":"HEADING_4"},"elements":[{"textRun":{"content":"H4\n"}}]}}]}}`,
	}
	for name, in := range inputs {
		t.Run(name, func(t *testing.T) {
			var doc struct {
				Body  *docBody `json:"body"`
				Lists docLists `json:"lists"`
			}
			if err := json.Unmarshal([]byte(in), &doc); err != nil {
				t.Fatalf("unmarshal input: %v", err)
			}
			got := docsJSONToMarkdown(doc.Body, doc.Lists)
			var want string
			if err := json.Unmarshal(raw[name], &want); err != nil {
				t.Fatalf("golden missing case %q: %v", name, err)
			}
			if got != want {
				t.Fatalf("mismatch:\n got: %q\nwant: %q", got, want)
			}
		})
	}
}
